import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"机器人推送（对外事件流）","description":"灵萌 OpenStream 对外事件流：流配置、接入点、回调日志与接入指南，对接企业微信/钉钉/自建脚本。","frontmatter":{"title":"机器人推送（对外事件流）","description":"灵萌 OpenStream 对外事件流：流配置、接入点、回调日志与接入指南，对接企业微信/钉钉/自建脚本。"},"headers":[],"relativePath":"features/open-stream.md","filePath":"features/open-stream.md","lastUpdated":1785051348000}'),o={name:"features/open-stream.md"};function i(n,t,s,d,h,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="机器人推送-对外事件流" tabindex="-1">机器人推送（对外事件流） <a class="header-anchor" href="#机器人推送-对外事件流" aria-label="Permalink to &quot;机器人推送（对外事件流）&quot;">​</a></h1><p>路径：<strong>通知控制台 → 机器人推送</strong></p><p>把站内业务事件（笔记发布、外卖订单、抽奖等）以 JSON 形式推给<strong>你自己的脚本或机器人中转服务</strong>。<br> 灵萌<strong>不会</strong>直接替你发到 QQ / 钉钉；你需要用 API Key 拉取或接收回调后再转发。</p><div class="tip custom-block"><p class="custom-block-title">不要和「官方机器人」搞混</p><table tabindex="0"><thead><tr><th>名称</th><th>菜单位置</th><th>用途</th></tr></thead><tbody><tr><td><strong>官方机器人</strong></td><td>用户体系 → 官方机器人</td><td>站内助手账号、对话回复</td></tr><tr><td><strong>机器人推送</strong>（本文）</td><td>通知控制台 → 机器人推送</td><td>对外事件流 / Webhook</td></tr></tbody></table></div><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>模块已开通（<strong>系统设置 → 我的模块</strong>）</li><li>若用 HTTP 回调：你的接收地址须公网 HTTPS 可达</li><li>明确要订阅哪些事件（见下方事件列表）</li></ul><hr><h2 id="三步上手" tabindex="-1">三步上手 <a class="header-anchor" href="#三步上手" aria-label="Permalink to &quot;三步上手&quot;">​</a></h2><h3 id="第一步-流配置" tabindex="-1">第一步：流配置 <a class="header-anchor" href="#第一步-流配置" aria-label="Permalink to &quot;第一步：流配置&quot;">​</a></h3><p>路径：<strong>通知控制台 → 机器人推送 → 流配置</strong></p><ol><li>选择目标区域（或平台默认，区域编号 0）</li><li>打开 <strong>启用对外事件流</strong></li><li>按需勾选允许的能力：HTTP 回调 / 内容拉取 / WebSocket</li><li>勾选 <strong>允许事件类型</strong>（未勾选的事件，接入点即使订阅也收不到）</li><li>按需调整：最大接入点数、Payload 档位（精简 / 标准 / 完整）、重试与超时、限流</li><li><strong>保存</strong></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>关闭「启用对外事件流」后，该区域不写入事件，也不能新建接入点。<br> 未单独配置的区域会继承平台默认（region_id = 0）。</p></div><h3 id="第二步-新建接入点" tabindex="-1">第二步：新建接入点 <a class="header-anchor" href="#第二步-新建接入点" aria-label="Permalink to &quot;第二步：新建接入点&quot;">​</a></h3><p>路径：<strong>通知控制台 → 机器人推送 → 接入点</strong>（页内标题也可能写作「机器人接入点」）</p><ol><li><strong>新建接入点</strong></li><li>绑定区域，选择分类（如笔记转发 / 外卖告警 / 混合）</li><li>多选订阅事件（须在流配置白名单内）</li><li>选择取数方式： <ul><li><strong>Pull 拉取</strong> — 你的程序定时来取</li><li><strong>HTTP 回调</strong> — 事件发生时 POST 到你的 URL</li><li><strong>WebSocket</strong> — 长连接接收</li></ul></li><li>若回调：填写回调 URL、Secret；可选 IP 白名单</li><li>保存后 <strong>立刻复制 API Key</strong>（通常只显示一次）</li></ol><h3 id="第三步-对接与排障" tabindex="-1">第三步：对接与排障 <a class="header-anchor" href="#第三步-对接与排障" aria-label="Permalink to &quot;第三步：对接与排障&quot;">​</a></h3><ol><li>用 API Key 按 <strong>接入指南</strong> 写脚本或配置中转服务</li><li>日常看 <strong>推送概览</strong>（已启用区域、接入点、今日事件、WS 在线）</li><li>失败看 <strong>回调日志</strong>，可补发 / 重放</li></ol><p>路径：<strong>通知控制台 → 机器人推送 → 接入指南</strong>（站内有官方三步说明与取数方式说明）。</p><hr><h2 id="常见事件类型-页面标签" tabindex="-1">常见事件类型（页面标签） <a class="header-anchor" href="#常见事件类型-页面标签" aria-label="Permalink to &quot;常见事件类型（页面标签）&quot;">​</a></h2><p>笔记发布、外卖新订单、外卖已接单、外卖已取消、骑手已分配、抽奖开始、抽奖开奖、圈子公告等（以页面勾选项为准）。</p><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>流配置已启用，事件类型已勾选</li><li>接入点启用且 Key 已保存</li><li>触发一条真实业务（如发笔记、下外卖单）</li><li><strong>推送概览</strong> 今日事件增加；Pull/回调/WS 侧收到 JSON</li><li>回调失败时 <strong>回调日志</strong> 有失败原因，修复后可补发</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>接入点收不到</td><td>流配置是否启用；事件是否在白名单；接入点是否订阅且启用</td></tr><tr><td>回调一直失败</td><td>URL 是否 HTTPS 可达；验签 Secret；IP 白名单是否误拦</td></tr><tr><td>Key 丢了</td><td>在接入点执行轮换 Key，旧 Key 失效，请同步更新脚本</td></tr><tr><td>和站内通知重复</td><td>二者独立：站内走 <a href="/features/notification">通知与推送</a>；对外走本文</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/notification">通知与推送</a></li><li><a href="/features/bot-notify">官方机器人</a></li><li><a href="/features/takeaway">外卖</a></li></ul>',31)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
